// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public {
        c = new demo();
    }

    // Fuzz the token address and amount; force the recipient list empty.
    function testFuzz_property(address caddress, uint256 v) public {
        address[] memory tos = new address[](0);

        bool ok = true;
        try c.transfer(address(this), caddress, tos, v) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: require(_tos.length > 0) makes every empty-array call revert.
        // Mutant: guard removed, so empty-array calls succeed and return true.
        assertTrue(!ok, "empty recipient list must revert");
    }
}
